# SPDX-License-Identifier: Apache-2.0

# Enable basic printing functionality
CONFIG_PRINTK=y

# Enable the Real-Time Clock driver subsystem
CONFIG_RTC=y

# Enable the counter-based RTC driver. This is a generic driver that
# can provide RTC functionality on any board with a counter device.
# This requires a devicetree overlay to instantiate the device.
# For example, add an app.overlay file with:
# / {
#     chosen {
#         zephyr,rtc = &counter_rtc;
#     };
# };
#
# counter_rtc: rtc {
#     compatible = "zephyr,counter-rtc";
#     status = "okay";
# };
CONFIG_COUNTER_RTC=y
